    f32 unk_0C;                     /* 0x0C */
    u8 pad_10[0x10];
    char *dialog_name;              /* 0x20 */
    u8 pad_24[0x1C];
    s32 clip_volume;                /* 0x40 */
    s32 elevator;                   /* 0x44: index of the elevator moby */
    s32 clip_volume_b;              /* 0x48 */
    u8 pad_4C[0x34];
    u8 body_manip[0x10];            /* 0x80 */
    u8 pad_90[0x54];
    f32 unk_E4;                     /* 0xE4 */
    f32 unk_E8;                     /* 0xE8 */
    u8 pad_EC[0x4];
    f32 height;                     /* 0xF0 */
    u8 pad_F4[0xC];
    u8 head_manip[0x10];            /* 0x100 */
    u8 pad_110[0x58];
    f32 unk_168;                    /* 0x168 */
    u8 pad_16C[0x14];
    Vec4A look_pos;                 /* 0x180 */
    u8 pad_190[0x4];
    s32 look_timer;                 /* 0x194 */
