/* Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/l14/gameplay/entities/002df080.c, FUN_L14_002ece00. */
void update_flying_bolt(struct Moby *m) {
    L14BoltVars *v = (L14BoltVars *)m->pvars;
    Vec4 old;
    Vec4 target;
    L14BoltSweep sweep;
    Vec4 aim;
    Vec4 dir;
    Vec4 spark;
    void *ignore;
    struct Moby *hit;
    int pass;
    int tries;
    int i;
    int j;

    qcopy(&old, &m->pos);
    FastVecAdd(&m->pos, &m->pos, &v->vel);
    qcopy(&target, &m->pos);
    ignore = v->ignore;
    qcopy(&aim, &v->vel);
    aim.f[2] = 0.0f;
    vec_set_length_xy(&aim, &aim, 1.0f);
    tries = 0;
    aim.f[2] = 1.0f;
    InitDirectionalHitQuery(&sweep, m, 0x10001, &aim, 1.0f);
    sweep.flag18 = 1;
    sweep.flag19 = 1;
    pass = v->solid == 0;
    if (vec_distance_xy(&m->pos, &v->origin) > 30.0f) {
        if (m->visible != 0) {
            for (i = 0; i < 3; i++) {
                spark.q = 0;
                spark.f[0] = random_float_between(-1.0f, 1.0f);
                spark.f[1] = random_float_between(-1.0f, 1.0f);
                spark.f[2] = random_float_between(-1.0f, 1.0f);
                dir.q = spark.q;
                vec_scale_to_length(&dir, &dir, FastVecLength(&spark) * 0.1f);
                FastVecAdd(&dir, &spark, &dir);
                vec_scale_to_length(&dir, &dir, random_float_between(g_frame_time + g_frame_time, g_frame_time * 4.0f));
                spawn_projectile_expiry_particle(&m->pos, &dir);
            }
        }
        DeleteMoby(m);
        return;
    }
    while (tries < 3 && coll_line(&old, &target, pass, ignore, 0) != 0) {
        hit = oltanis_coll_hit.moby;
        tries++;
        if (hit != 0 && hit->oclass == 0xFC) {
            qcopy(&old, &oltanis_coll_hit.pos);
            ignore = hit;
            continue;
        }
        coll_line(&old, &target, pass, ignore, &sweep);
        qcopy(&m->pos, &oltanis_coll_hit.pos);
        if (m->visible != 0) {
            for (j = 0; j < 5; j++) {
                spark.q = 0;
                spark.f[0] = random_float_between(-1.0f, 1.0f);
                spark.f[1] = random_float_between(-1.0f, 1.0f);
                spark.f[2] = random_float_between(-1.0f, 1.0f);
                dir.q = spark.q;
                vec_reflect(&spark, &v->vel, oltanis_coll_hit_normal);
                vec_scale_to_length(&dir, &dir, FastVecLength(&spark) * 0.5f);
                FastVecAdd(&dir, &spark, &dir);
                vec_scale_to_length(&dir, &dir, random_float_between(g_frame_time * 3.0f, g_frame_time * 6.0f));
                PartType27Spawn((char *)&m->pos, (char *)&dir, 0x7F2F4F6F,
                                 rand_range(scale_ticks(10), scale_ticks(15)), 30000.0f);
            }
        }
        Moby_PlaySound(0, 0, m);
        DeleteMoby(m);
        return;
    }
    if (m->pos.x < 2.0f || m->pos.x > 1021.0f || m->pos.y < 2.0f || m->pos.y > 1021.0f ||
        m->pos.z < 2.0f || m->pos.z > 1021.0f) {
        DeleteMoby(m);
    }
}
